def rule_form_10k_h1(doc: dict) -> list[dict]:
    """Match H1/section_header spans with FORM 10-K."""
    import re
    try:
        return [
            span for span in doc.get("texts", [])
            if span.get("label") == "section_header"
            and re.search(r"\bFORM\s+10-K\b", span.get("text") or "", re.I)
        ]
    except Exception:
        return []

def rule_annual_report_page1(doc: dict) -> list[dict]:
    """Match page-1 spans containing ANNUAL REPORT, typically used on Form 10-K covers."""
    try:
        return [
            span for span in doc.get("texts", [])
            if span.get("page_no") == 1 and "ANNUAL REPORT" in (span.get("text") or "").upper()
        ]
    except Exception:
        return []

def rule_form_code_exact_text(doc: dict) -> list[dict]:
    """Match spans whose text is exactly FORM 10-K, FORM 10-Q, or FORM 8-K."""
    import re
    try:
        return [
            span for span in doc.get("texts", [])
            if re.fullmatch(r"\s*FORM\s+(10-K|10-Q|8-K)\s*", span.get("text") or "", re.I)
        ]
    except Exception:
